// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint96 amount) public {
        vm.assume(depositor != address(0));
        uint256 bounded = bound(uint256(amount), 1, 1 ether);

        Reverter reverter = new Reverter();

        vm.deal(depositor, bounded);

        vm.prank(depositor);
        c.deposit{value: bounded}();

        vm.deal(address(reverter), bounded);
        vm.prank(address(reverter));
        c.deposit{value: bounded}();

        bool ok;
        vm.prank(address(reverter));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert on receive");
    }
    receive() external payable {
        revert("revert on receive");
    }
}
